        if args.probe_demo_weblog_report:
            # Use an isolated fixture on the disposable guest disk. WebLogRep
            # reads this file and writes a report; no host or user log files
            # are exposed to the program.
            fixture = (
                '47.105.230.89 - - [05/Jun/2017:01:00:00 -0700] '
                '"GET /TOS_Distro.ISO HTTP/1.1" 200 16000000 "-" '
                '"Wget/1.19 (freebsd11.0)" "www.templeos.org"\n'
                '47.87.74.3 - - [05/Jun/2017:02:00:01 -0700] '
                '"GET /About.html HTTP/1.1" 200 456 "-" '
                '"curl/7.19.7 (x86_64-redhat-linux-gnu)" '
                '"www.templeos.org"\n'
            ).encode()
            # zrecv accepts only .ZC-named files, but stores arbitrary bytes;
            # ParseLogFiles reads this fixture as plain text regardless of its
            # suffix.
            upload_source('WebLogProbe.ZC', fixture)
            source_files = (
                'System/DolDoc/DocRecalcLib.ZC',
                'System/DolDoc/DocGet.ZC',
                'System/DolDoc/DocNew.ZC',
                'System/DolDoc/DocFile.ZC',
                'Demo/WebLogDemo/WebLogRep.ZC',
            )
            for source in source_files:
                upload_source(pathlib.Path(source).name,
                              (ROOT / 'upstream/pinned' / source).read_bytes())
            weblog_source = (ROOT / 'upstream/pinned/Demo/WebLogDemo/WebLogRep.ZC').read_bytes()
            def weblog_replace(source_data, old, new):
                if source_data.count(old) != 1:
                    raise RuntimeError(f'WebLogRep diagnostic anchor mismatch: {old!r}')
                return source_data.replace(old, new, 1)
            weblog_source = weblog_replace(weblog_source, b'\tI64 i;\n\n\t"%$$Q\\n", name;',
                           b'\tI64 i, probe_stage=0;\n\n\t"%$$Q\\n", name;')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\ttmplg->datetime = Struct2Date(&ds);',
                           b'\t\t\t\ttmplg->datetime = Struct2Date(&ds);\n'
                           b'\t\t\t\tprobe_stage = 1;')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\ttmplg->datetime -= (i / 100 + i % 100 / 60.0) * CDATE_FREQ * 60 * 60;',
                           b'\t\t\t\ttmplg->datetime -= (i / 100 + i % 100 / 60.0) * CDATE_FREQ * 60 * 60;\n'
                           b'\t\t\t\tprobe_stage = 2;')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\tif (!(Str2Date("1/1/2017") <= tmplg->datetime < Str2Date("1/1/2050")))',
                           b'\t\t\t\tprobe_stage = 3;\n'
                           b'\t\t\t\tif (!(Str2Date("1/1/2017") <= tmplg->datetime && tmplg->datetime < Str2Date("1/1/2050")))')
            weblog_source = weblog_replace(weblog_source,
                           b'\tif (dstart <= tmplg->datetime <= dend',
                           b'\tif (dstart <= tmplg->datetime && tmplg->datetime <= dend')
            weblog_source = weblog_replace(weblog_source,
                           b"\t\t'A' <= tmplg->file[1] <= 'Z'",
                           b"\t\t'A' <= tmplg->file[1] && tmplg->file[1] <= 'Z'")
            # DateGet is an interactive form; this probe tests report logic
            # with the parser's exact min/max dates and no keyboard prompts.
            weblog_source = weblog_replace(weblog_source,
                           b'\t\tdstart\t= DateGet("Start(%D):", dstart);',
                           b'\t\tdstart\t= dstart;')
            weblog_source = weblog_replace(weblog_source,
                           b'\t\tdend\t= DateGet("End  (%D):", dend);',
                           b'\t\tdend\t= dend;')
            # The test supplies the output filename explicitly, so avoid the
            # interactive DocForm confirmation that cannot be completed by a
            # one-line guest command.
            weblog_source = weblog_replace(weblog_source,
                           b'\t\tDocWrite(DocPut, TRUE);',
                           b'\t\tDocWrite(DocPut, FALSE);')
            weblog_source = weblog_replace(weblog_source,
                           b'\tLogListDel(head);\n}\n\n#if __CMD_LINE__',
                           b'\tLogListDel(head);\n'
                           b'\tPrint("WEBLOG_RETURNED\\n");\n'
                           b'}\n\n#if __CMD_LINE__')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\twhile (*src++ != \']\');',
                           b'\t\t\t\twhile (*src++ != \']\');\n\t\t\t\tprobe_stage = 4;')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\tif (!StrNCompare(src, "GET ", 4))',
                           b'\t\t\t\tprobe_stage = 5;\n'
                           b'\t\t\t\tif (!StrNCompare(src, "GET ", 4))')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\t\ttmplg->size = Str2I64(src, 10, &src);',
                           b'\t\t\t\t\ttmplg->size = Str2I64(src, 10, &src);\n'
                           b'\t\t\t\t\tprobe_stage = 6;')
            weblog_source = weblog_replace(weblog_source, b'\t\t\t\t\tQueueInsert(tmplg, head->last);',
                           b'\t\t\t\t\tQueueInsert(tmplg, head->last);\n'
                           b'\t\t\t\t\tprobe_stage = 7;')
            weblog_source = weblog_source.replace(
                b'Fs->catch_except = TRUE;\n\t\t\t\t"%$$Q\\n", doc_e->tag;',
                b'Fs->catch_except = TRUE;\n'
                b'\t\t\t\tPrint("weblog reject stage=%d date=%d start=%d end=%d code=%d size=%d\\n", '
                b'probe_stage, tmplg->datetime, Str2Date("1/1/2017"), '
                b'Str2Date("1/1/2050"), tmplg->code, tmplg->size);\n'
                b'\t\t\t\t"%$$Q\\n", doc_e->tag;')
            weblog_source += (
                b'\nI64 WebLogProbeDump()\n'
                b'{\n'
                b'\tCDate dstart=I64_MAX, dend=I64_MIN;\n'
                b'\tLogStruct *head=ParseLogFiles("WebLogProbe.ZC",&dstart,&dend), *p=head->next;\n'
                b'\tI64 count=0, len, range_ok, no_query, path_ok, alpha_ok, size_ok, no_dir, wb_ok, family_ok;\n'
                b'\twhile (p!=head) {\n'
                b'\t\tlen=StrLen(p->file);\n'
                b'\t\trange_ok=dstart<=p->datetime && p->datetime<=dend;\n'
                b'\t\tno_query=!StrOcc(p->file,\'?\'); path_ok=len>2;\n'
                b'\t\talpha_ok=\'A\'<=p->file[1] && p->file[1]<=\'Z\'; size_ok=p->size!=0;\n'
                b'\t\tno_dir=p->file[len-1]!=\'/\';\n'
                b'\t\twb_ok=len<3 || MemCompare(&p->file[1],"Wb",2);\n'
                b'\t\tfamily_ok=len<7 || MemCompare(&p->file[1],"Family",6);\n'
                b'\t\tPrint("WEBLOG_ROW date=%d code=%d size=%d file=%s keep=%d flags=%d%d%d%d%d%d%d%d\\n",p->datetime,p->code,p->size,p->file,IsKeeper(p,dstart,dend),range_ok,no_query,path_ok,alpha_ok,size_ok,no_dir,wb_ok,family_ok);\n'
                b'\t\tcount++; p=p->next;\n'
                b'\t}\n'
                b'\tPrint("WEBLOG_COUNT=%d start=%d end=%d\\n",count,dstart,dend);\n'
                b'\tLogListDel(head);\n'
                b'\treturn 42;\n'
                b'}\n'
                b'I64 WebLogProbeRead()\n'
                b'{\n'
                b'\tI64 size=0; FileRead("/WebLogProbe.DD",&size);\n'
                b'\tPrint("WEBLOG_FILE size=%d\\n", size);\n'
                b'\treturn size;\n'
                b'}\n')
            upload_source('WebLogRep.ZC', weblog_source)
            focus_graphical_terminal()
            run_graphical_terminal_command(
                'demo-weblog-cd-root', 'Cd("..");', 'ans=', timeout=20)
            for module in ('DocRecalcLib', 'DocGet', 'DocNew', 'DocFile',
                           'WebLogRep'):
                path = f'{module}.ZC'
                run_graphical_terminal_command(
                    f'demo-weblog-load-{module}', f'zload {path}',
                    f'loaded /{path}', timeout=60)
            probe_screen = run_graphical_terminal_command(
                'demo-weblog-parse', 'zcall WebLogProbeDump',
                'WEBLOG_COUNT=', timeout=30)
            if 'WEBLOG_COUNT=2' not in probe_screen[3]:
                raise RuntimeError('WebLogRep fixture parser did not keep both rows; '
                                   f'see {graphical_path("demo-weblog-parse-result")}\n'
                                   + probe_screen[3])
            launch_screen = run_graphical_terminal_command(
                'demo-weblog-launch',
                'WebLogRep("WebLogProbe.ZC", "WebLogProbe.DD");',
                'WEBLOG_RETURNED', timeout=45, accept_autocomplete=True)
            launch_text = launch_screen[3]
            if '/About.html' not in launch_text or '/TOS_Distro.ISO' not in launch_text:
                raise RuntimeError('WebLogRep did not display both fixture paths:\n'
                                   + launch_text)
            report_screen = run_graphical_terminal_command(
                'demo-weblog-read-report', 'zcall WebLogProbeRead',
                'WEBLOG_FILE size=', timeout=30)
            report = report_screen[3]
            size_match = re.search(r'WEBLOG_FILE size=(\d+)', report)
            if not size_match or int(size_match.group(1)) <= 0:
                raise RuntimeError('WebLogRep report was not persisted to the guest disk:\n'
                                   + report)
            run_graphical_terminal_command(
                'demo-weblog-shell-recovery', '40+2;', 'ans=0x2A=42', timeout=20)
            command('zstatus', 'failed=0')
            print('PASS WebLogRep parsed two synthetic requests, rendered a report, '
                  'and returned to the guest shell', flush=True)
            raise SystemExit(0)
        if args.probe_popup_menu:
            command('zload /Tests/PopupMenus.ZC', 'zc: loaded /Tests/PopupMenus.ZC')
            command('zcall PopupParentHitTestChecks',
                    'zc => 0x000000000000002a')
            print('PASS modal popup hit testing over a later-in-ring parent',
                  flush=True)
            focus_graphical_terminal()
            command('zc TaskExe(bootstrap_gui_terminal_task,NULL,"PopUpColor;",1<<JOBf_FREE_ON_COMPLETE);',
                    'zc: executed')
            require_graphical_text('popup-menu-choice', 'RED', timeout=10,
                                   foreground_threshold=25000)
            output = command(
                'zc Print("popup_point=%X\\n",StockPopupPoint("__RED"));',
                'popup_point=')
            point = int(re.search(r'popup_point=([0-9A-Fa-f]+)', output).group(1), 16)
            if point == 0xffffffffffffffff:
                raise RuntimeError('PopUpMenu did not expose the selectable entry')
            move_graphical_pointer(point & 0xffffffff, point >> 32)
            graphical_mouse_button('left', True)
            time.sleep(.2)
            graphical_mouse_button('left', False)
            command('zstatus', 'failed=0')
            command('zc Print("popup_menu_focus=%d\\n",sys_focus_task==bootstrap_gui_terminal_task);',
                    'popup_menu_focus=1')
            command('zstatus', 'failed=0')
            print('PASS live color-picker PopUpMenu selection and focus return', flush=True)
            raise SystemExit(0)
        if args.probe_xcaliber:
            command('zload /Tests/PopupMenus.ZC',
                    'zc: loaded /Tests/PopupMenus.ZC')
            focus_graphical_terminal()
            run_graphical_terminal_command(
                'xcaliber-ready', '40+2;', 'ans=0x2A=42')
            # Submit the launcher as a task to the focused GUI terminal. Typing
            # the long function name through QMP is flaky under the live
            # graphics load and can duplicate characters before the app starts;
            # this exercises the same GUI-terminal launcher without conflating
            # that input path with X-Caliber's own event loop.
            command('zc TaskExe(bootstrap_gui_terminal_task,NULL,'
                    '"BootstrapGuiTerminalXCaliberRun();",'
                    '1<<JOBf_FREE_ON_COMPLETE);', 'zc: executed')
            require_graphical_text('xcaliber-solar-storm',
                                   'Face away from Sun in solar storm', timeout=20)
            # Resolve the actual OKAY link in the game's one-time popup.
            # Its task/window geometry can vary with guest display settings.
            output = command(
                'zc Print("xcaliber_okay_point=%X\\n",'
                'StockPopupPoint("OKAY")); '
                'Print("xcaliber_suppress_point=%X\\n",'
                'StockPopupPoint("Do not show this message again."));',
                'xcaliber_okay_point=')
            point_match = re.search(
                r'xcaliber_okay_point=([0-9A-Fa-f]+)', output)
            if not point_match:
                raise RuntimeError('could not locate X-Caliber popup OKAY link:\n'+output)
            point = int(point_match.group(1), 16)
            if point == 0xffffffffffffffff:
                raise RuntimeError('X-Caliber one-time popup has no OKAY link')
            suppress_match = re.search(
                r'xcaliber_suppress_point=([0-9A-Fa-f]+)', output)
            if suppress_match:
                suppress_point = int(suppress_match.group(1), 16)
                if suppress_point != 0xffffffffffffffff:
                    move_graphical_pointer(suppress_point & 0xffffffff,
                                           suppress_point >> 32)
                    graphical_mouse_button('left', True)
                    time.sleep(0.2)
                    graphical_mouse_button('left', False)
                    print('X-Caliber one-time popup suppression checkbox clicked',
                          flush=True)
                    graphical_screen('xcaliber-popup-after-suppress-click')
                    command('zstatus', 'keyboard_focus=')
                    output = command(
                        'zc Print("xcaliber_okay_after_suppress=%X\\n",'
                        'StockPopupPoint("OKAY"));',
                        'xcaliber_okay_after_suppress=')
                    after_suppress = re.search(
                        r'xcaliber_okay_after_suppress=([0-9A-Fa-f]+)', output)
                    if after_suppress:
                        point = int(after_suppress.group(1), 16)
                        if point == 0xffffffffffffffff:
                            raise RuntimeError('X-Caliber popup lost its OKAY link')
            move_graphical_pointer(point & 0xffffffff, point >> 32)
            time.sleep(0.2)
            graphical_mouse_button('left', True)
            time.sleep(0.2)
            graphical_mouse_button('left', False)
            # The popup declares OKAY with LE=1. Its left-expression action
            # is activated by Space, which the stock WinMgr sends on a click.
            qmp_send_key('spc')
            command('zstatus', 'keyboard_focus=')
            require_graphical_text_absent(
                'xcaliber-solar-storm-dismissed',
                'Face away from Sun in solar storm', timeout=5)
            focus_output = command(
                'zc Print("xcaliber_focus_app=%d focus_title=%s\\n",'
                'StrCompare(sys_focus_task->task_title,"X-Caliber")==0, '
                'sys_focus_task->task_title);', 'xcaliber_focus_app=')
            focus_match = re.search(
                r'xcaliber_focus_app=(\d+) focus_title=([^\r\n]+)',
                focus_output)
            print('X-Caliber focus after popup: '
                  + (focus_match.group(2) if focus_match else 'unknown')
                  + ' (X-Caliber task focused=' +
                  (focus_match.group(1) if focus_match else '?') + ')',
                  flush=True)
            time.sleep(0.3)
            task_status = command('zstatus', 'keyboard_focus=X-Caliber')
            focus = re.search(r'keyboard_focus=([^\r\n]+)', task_status)
            print('X-Caliber task focus: '
                  +(focus.group(1) if focus else 'unknown'), flush=True)
            # InitLevel draws the player ship before its one-key pause ends,
            # so ship visibility alone does not prove gameplay has started.
            # The blinking "Level N" label is centered below the ship; sample
            # it over a full blink interval after Space to verify the pause is
            # gone before measuring controls.
            def level_message_visible(screen):
                width, height, pixels, _ = screen
                left, top, right, bottom = 360, 340, 440, 370
                count = 0
                for y in range(top, min(bottom, height)):
                    for x in range(left, min(right, width)):
                        offset = (y * width + x) * 3
                        if pixels[offset:offset + 3] != b'\0\0\0':
                            count += 1
                return count >= 20

            deadline = time.monotonic() + 8
            before = None
            while time.monotonic() < deadline:
                candidate = graphical_screen('xcaliber-level-pause')
                if level_message_visible(candidate):
                    before = candidate
                    break
                time.sleep(0.1)
            if before is None:
                raise RuntimeError('X-Caliber level-start pause was not visible in scanout')
            started = False
            for _ in range(4):
                qmp_send_key('ret')
                clear_since = None
                clear_deadline = time.monotonic() + 2.5
                while time.monotonic() < clear_deadline:
                    candidate = graphical_screen('xcaliber-gameplay-before-input')
                    if level_message_visible(candidate):
                        clear_since = None
                    elif clear_since is None:
                        clear_since = time.monotonic()
                    elif time.monotonic() - clear_since >= 1.2:
                        before = candidate
                        started = True
                        break
                    time.sleep(0.1)
                if started:
                    break
            if not started:
                raise RuntimeError('X-Caliber level-start pause did not clear after Space')
            time.sleep(0.5)
            if 'Face away from Sun in solar storm' in before[3]:
                raise RuntimeError('X-Caliber help popup remained over gameplay')
            idle = graphical_screen('xcaliber-gameplay-idle')
            colors_before = Counter(tuple(before[2][i:i+3])
                                    for i in range(0, len(before[2]), 3))
            if len(colors_before) < 8 or sum(
                    count for color, count in colors_before.items()
                    if color != (0, 0, 0)) < 3000:
                raise RuntimeError('X-Caliber did not render its gameplay scene')
            # The focused task paints the game across the full framebuffer;
            # its ship is near the center rather than in the old inline-window
            # coordinates used by the previous probe.
            player_bounds = (350, 270, 450, 360)
            if level_message_visible(idle):
                raise RuntimeError('X-Caliber level-start pause remained visible after Space')
            if len(rgb_coordinates_in(idle, (0, 151, 162), player_bounds)) < 5:
                raise RuntimeError('X-Caliber gameplay frame has no visible player ship')
            # Collect a no-input motion baseline to avoid treating moving
            # enemies, flares, or the blinking pause label as player control.
            time.sleep(0.5)
            idle_after_wait = graphical_screen('xcaliber-gameplay-idle-baseline')
            ship_bounds = (340, 250, 460, 375)
            idle_motion = rgb_diff_count(idle, idle_after_wait, ship_bounds)
            xcaliber_control_failures = []
            qmp_key_edges(['right'], True)
            # This app runs inside a cooperative task and can spend most of a
            # host-side sleep waiting for its next frame. Keep the key held
            # until the guest-side frame trace confirms that the bitmap and
            # thrust state were sampled; otherwise a short down/up pair can
            # be dequeued together and look like a failed control.
            until(b'bitmap_right=1', timeout=10)
            until(b'\n', timeout=10)
            right_held_frame = None
            right_motion = 0
            for sample in range(20):
                candidate = graphical_screen(
                    f'xcaliber-gameplay-right-held-{sample}')
                candidate_motion = rgb_diff_count(
                    idle_after_wait, candidate, ship_bounds)
                if candidate_motion > right_motion:
                    right_motion = candidate_motion
                    right_held_frame = candidate
                if right_motion >= max(12, idle_motion * 2):
                    break
                time.sleep(0.1)
            qmp_key_edges(['right'], False)
            time.sleep(0.75)
            right_frame = graphical_screen('xcaliber-gameplay-right')
            if right_held_frame is None:
                right_held_frame = right_frame
            if right_motion < max(12, idle_motion * 2):
                xcaliber_control_failures.append(
                    f'Right idle_diff={idle_motion} right_diff={right_motion}')
                print('INCONCLUSIVE X-Caliber Right visual response: '
                      f'idle_diff={idle_motion}, right_diff={right_motion}', flush=True)
            else:
                print('PASS X-Caliber right thruster changes the player ship: '
                      f'idle_diff={idle_motion}, right_diff={right_motion}', flush=True)
            time.sleep(0.3)
            before_left = graphical_screen('xcaliber-gameplay-before-left')
            if len(rgb_coordinates_in(before_left, (0, 151, 162),
                                     player_bounds)) < 5:
                raise RuntimeError('X-Caliber player ship disappeared before left input')
            # A same-duration counter-thrust can steer back toward the
            # starting orientation and make a correct opposite-direction
            # control look like a no-op in a before/after scanout diff.
            qmp_key_edges(['left'], True)
            until(b'bitmap_left=1', timeout=10)
            until(b'\n', timeout=10)
            left_held_frame = None
            left_motion = 0
            for sample in range(20):
                candidate = graphical_screen(
                    f'xcaliber-gameplay-left-held-{sample}')
                candidate_motion = rgb_diff_count(
                    before_left, candidate, ship_bounds)
                if candidate_motion > left_motion:
                    left_motion = candidate_motion
                    left_held_frame = candidate
                if left_motion >= max(12, idle_motion * 2):
                    break
                time.sleep(0.1)
            qmp_key_edges(['left'], False)
            time.sleep(0.75)
            left_frame = graphical_screen('xcaliber-gameplay-left')
            if left_held_frame is None:
                left_held_frame = left_frame
            if left_motion < max(12, idle_motion * 2):
                xcaliber_control_failures.append(
                    f'Left idle_diff={idle_motion} left_diff={left_motion}')
                print('INCONCLUSIVE X-Caliber Left visual response: '
                      f'idle_diff={idle_motion}, left_diff={left_motion}', flush=True)
            else:
                print('PASS X-Caliber left thruster changes the player ship: '
                      f'idle_diff={idle_motion}, left_diff={left_motion}', flush=True)
            # The stock control panel starts both size and fuse sliders at
            # zero. That makes a default gun shot a half-pixel-radius plot
            # with a 1/30-second fuse; it can disappear between QMP scanout
            # samples. Set both controls high through the visible UI so this
            # probe checks the normal configured projectile path.
            for control_x in (732, 766):
                move_graphical_pointer(control_x, 539)
                graphical_mouse_button('left', True)
                time.sleep(0.05)
                graphical_mouse_button('left', False)
                time.sleep(0.1)
            graphical_screen('xcaliber-gameplay-projectile-controls')
            before_space = graphical_screen('xcaliber-gameplay-before-space')
            player_before_space = rgb_centroid_in(
                before_space, (0, 151, 162), player_bounds)
            qmp_key_edges(['spc'], True)
            # The Space key is consumed inside the app's frame/message loop.
            # Wait for the guest-side trace before capturing; a fixed host
            # sleep can snapshot the previous frame before the input is read.
            until(b'xcal_fire phase=1', timeout=10)
            until(b'\n', timeout=10)
            firing_trace = re.findall(
                r'xcal_fire phase=(\d+) level=(\d+) shots=(\d+) '
                r'x=(-?\d+) y=(-?\d+)',
                log_path.read_text(errors='replace'))
            if not firing_trace or firing_trace[-1][0] != '1':
                raise RuntimeError('X-Caliber firing trace has no completed shot '
                                   f'record: {firing_trace[-4:]}')
            shot_x, shot_y = (int(value) for value in firing_trace[-1][3:5])
            # At maximum size/fuse the shot moves quickly across the screen.
            # Include enough of its forward path for the first post-input
            # scanout, instead of sampling only the spawn pixel.
            shot_bounds = (max(0, shot_x - 64), max(0, shot_y - 64),
                           min(800, shot_x + 65), min(600, shot_y + 65))
            idle_shot_motion = rgb_diff_count(
                idle, idle_after_wait, shot_bounds)
            shot_motion = 0
            space_held_frame = None
            for sample in range(20):
                space_held_frame = graphical_screen(
                    f'xcaliber-gameplay-space-scanout-{sample}')
                shot_motion = rgb_diff_count(
                    before_space, space_held_frame, shot_bounds)
                if shot_motion > idle_shot_motion:
                    break
                time.sleep(0.1)
            qmp_key_edges(['spc'], False)
            time.sleep(0.1)
            space_frame = graphical_screen('xcaliber-gameplay-space')
            player_after_space = rgb_centroid_in(
                space_frame, (0, 151, 162), player_bounds)
            if player_before_space is None or player_after_space is None:
                raise RuntimeError('X-Caliber player ship disappeared during Space input')
            space_motion = rgb_diff_count(before_space, space_held_frame, ship_bounds)
            print('X-Caliber Space held scanout diff in ship bounds: '
                  f'{space_motion} pixels (projectile check remains inconclusive)',
                  flush=True)
            while select.select([guest.stdout], [], [], 0)[0]:
                data = os.read(guest.stdout.fileno(), 65536)
                if not data:
                    break
                buf.extend(data)
                log.write(data)
                log.flush()
            fire_trace = re.findall(
                r'xcal_fire phase=(\d+) level=(\d+) shots=(\d+) '
                r'x=(-?\d+) y=(-?\d+)',
                log_path.read_text(errors='replace'))
            fired = any(
                before_phase == '0' and after_phase == '1' and
                before_level == after_level and int(after_shots) > int(before_shots)
                for (before_phase, before_level, before_shots, _, _),
                    (after_phase, after_level, after_shots, _, _)
                in zip(fire_trace, fire_trace[1:]))
            if not fired:
                raise RuntimeError('X-Caliber Space did not enqueue a shot; '
                                   f'fire trace={fire_trace[-8:]}')
            print('X-Caliber projectile region motion: '
                  f'baseline={idle_shot_motion} shot={shot_motion} '
                  f'point=({shot_x},{shot_y})', flush=True)
            if shot_motion <= idle_shot_motion:
                print('INCONCLUSIVE X-Caliber projectile visibility: the guest '
                      'enqueued a shot, but its local scanout did not change',
                      flush=True)
            else:
                print('PASS X-Caliber Space projectile is visible in scanout',
                      flush=True)
            # X-Caliber spends most of each frame in its ODE update. Keep
            # Escape down long enough for its polling loop to sample the
            # transition instead of using the generic 100 ms key tap.
            qmp_send_key_hold('esc', 1000)
            time.sleep(0.5)
            # Probe return through scanout and the guest keyboard. A serial
            # `zstatus` request can stall while the graphical app owns the
            # foreground task, so it is not a reliable way to decide whether
            # Escape returned to the terminal.
            returned = None
            return_deadline = time.monotonic() + 8
            while time.monotonic() < return_deadline:
                candidate = graphical_screen('xcaliber-after-escape')
                if ('Directory of /' in candidate[3] or
                        'Help & Index' in candidate[3]):
                    returned = candidate
                    break
                time.sleep(0.1)
            if returned is None:
                try:
                    input_diagnostics = command(
                        'zstatus', 'xcal_key_dequeues', timeout=8)
                except Exception as exc:
                    input_diagnostics = f'\npost-input zstatus unavailable: {exc}'
                raise RuntimeError('X-Caliber did not return after QMP Escape; see '
                                   f'{graphical_path("xcaliber-after-escape")}\n'
                                   +candidate[3] + input_diagnostics)
            print('PASS X-Caliber Escape returned to the graphical terminal', flush=True)
            run_graphical_terminal_command('xcaliber-exit-smoke', '40+7;',
                                           'ans=0x2F=47', timeout=12)
            print('PASS X-Caliber terminal accepts and executes commands after Escape',
                  flush=True)
            if xcaliber_control_failures:
                raise RuntimeError('X-Caliber arrow control scanout checks failed: '
                                   +'; '.join(xcaliber_control_failures))

        if args.probe_tothefront:
            command('zload /Tests/PopupMenus.ZC',
                    'zc: loaded /Tests/PopupMenus.ZC')
            focus_graphical_terminal()
            run_graphical_terminal_command(
                'tothefront-ready', '40+2;', 'ans=0x2A=42')
            type_graphical_prompt_line(
                'tothefront-launch',
                'ExeFile2("/Apps/ToTheFront/Run.ZC");')
            qmp_send_key('ret')
            require_graphical_text('tothefront-seed', 'GameSeed(0x', timeout=30)
            qmp_send_key('ret')

            def choose_tothefront_player(name):
                expected_player = ('Player 1 Type' if name.endswith('player1')
                                   else 'Player 2 Type')
                screen = require_graphical_text(
                    name, expected_player, timeout=15)
                player_text = re.search(re.escape(expected_player), screen[3])
                if not player_text:
                    raise RuntimeError('ToTheFront did not open a player type menu:\n'+screen[3])
                command(
                    'zc I64 ToTheFrontPickerDiag(){CDoc*d=sys_focus_task->display_doc;'
                    'CDocEntry*e;for(e=d->head.next;e!=d;e=e->next)'
                    'if(e->tag)'
                    'Print("picker_entry=%s LE=%016X flags=%X\\n",'
                    'e->tag,e->left_exp,e->de_flags);};'
                    'ToTheFrontPickerDiag;',
                    'picker_entry=')
                # Resolve the clickable link in the popup document itself;
                # menu geometry can change with font and task-window layout.
                output = command(
                    'zc Print("tothefront_human_point=%X\\n",'
                    'StockPopupPoint("Human"));',
                    'tothefront_human_point=')
                point_match = re.search(
                    r'tothefront_human_point=([0-9A-Fa-f]+)', output)
                if not point_match:
                    raise RuntimeError('could not locate Human in the AI picker:\n'+output)
                point = int(point_match.group(1), 16)
                if point == 0xffffffffffffffff:
                    raise RuntimeError('the AI picker has no selectable Human entry')
                move_graphical_pointer(point & 0xffffffff, point >> 32)
                graphical_mouse_button('left', True)
                time.sleep(0.1)
                graphical_mouse_button('left', False)
                # PopUpMenu returns the selected link on mouse-up. Sending a
                # second key here would be delivered to the next picker and
                # silently select its default entry too.
                time.sleep(0.5)
                graphical_screen(name+'-after-select')

            choose_tothefront_player('tothefront-player1')
            choose_tothefront_player('tothefront-player2')
            require_graphical_text(
                'tothefront-help', 'move or fire units.',
                timeout=20)
            output = command(
                'zc Print("tothefront_help_okay=%X\\n",'
                'StockPopupPoint("OKAY"));',
                'tothefront_help_okay=')
            point_match = re.search(
                r'tothefront_help_okay=([0-9A-Fa-f]+)', output)
            if not point_match:
                raise RuntimeError('could not locate ToTheFront help OK button:\n'+output)
            point = int(point_match.group(1), 16)
            if point == 0xffffffffffffffff:
                raise RuntimeError('ToTheFront help popup has no OK button')
            move_graphical_pointer(point & 0xffffffff, point >> 32)
            graphical_mouse_button('left', True)
            time.sleep(0.2)
            graphical_mouse_button('left', False)
            # DocMenu runs the selected DolDoc entry when DocEd exits.
            qmp_send_key('esc')
            require_graphical_text_absent(
                'tothefront-help-dismissed', 'move or fire units.', timeout=5)
            deadline = time.monotonic() + 30
            while True:
                match = graphical_screen('tothefront-turn')
                if rgb_pixels_in(match, (130, 188, 73), (0, 0, 640, 480)) > 100000:
                    break
                if time.monotonic() >= deadline:
                    raise RuntimeError('ToTheFront map lacks terrain/unit color variety')
                time.sleep(0.1)
            # Initial TurnNew banner shares the artillery-range palette and
            # can obscure input until its timeout; do not use it as baseline.
            time.sleep(3)
            match = graphical_screen('tothefront-artillery-ready')
            artillery = color_component_centers(
                match, (5, 124, 126), (0, 20, 640, 480), minimum=80)
            if not artillery:
                raise RuntimeError('ToTheFront artillery phase lacks a visible active artillery marker')
            baseline_yellow = rgb_pixels_in(match, (199, 171, 0),
                                            (0, 20, 640, 480))
            ordered = False
            for _, (start_x, start_y) in artillery:
                move_graphical_pointer(start_x, start_y)
                graphical_mouse_button('left', True)
                time.sleep(0.1)
                selected = graphical_screen('tothefront-artillery-selected')
                yellow = rgb_pixels_in(selected, (199, 171, 0),
                                        (0, 20, 640, 480))
                if yellow < baseline_yellow + 100:
                    graphical_mouse_button('left', False)
                    continue
                print(f'PASS ToTheFront selected artillery at {start_x},{start_y} '
                      f'and displayed its range ({yellow-baseline_yellow} yellow pixels)',
                      flush=True)
                # Adjacent hex centers. Retry the same gun if a target cell is
                # occupied; a queued order removes its pulsing active marker.
                for dx, dy in ((22, 0), (11, 17), (-11, 17), (-22, 0),
                               (-11, -17), (11, -17)):
                    move_graphical_pointer(start_x + dx, start_y + dy)
                    time.sleep(0.1)
                    graphical_mouse_button('left', False)
                    time.sleep(0.2)
                    after_order = graphical_screen('tothefront-order-attempt')
                    active_markers = color_component_centers(
                        after_order, (5, 124, 126), (0, 20, 640, 480), minimum=80)
                    if not any(abs(cx-start_x) <= 18 and abs(cy-start_y) <= 18
                               for _, (cx, cy) in active_markers):
                        print(f'PASS ToTheFront artillery accepted a plotted order '
                              f'to adjacent hex {start_x+dx},{start_y+dy}', flush=True)
                        ordered = True
                        match = after_order
                        break
                    move_graphical_pointer(start_x, start_y)
                    graphical_mouse_button('left', True)
                    time.sleep(0.1)
                if ordered:
                    break
                graphical_mouse_button('left', False)
            if not ordered:
                raise RuntimeError('ToTheFront did not visibly accept an artillery order')
            before_phase = match
            qmp_send_key('spc')
            deadline = time.monotonic() + 3
            while True:
                after_phase = graphical_screen('tothefront-next-phase')
                phase_message_changed = rgb_diff_count(
                    before_phase, after_phase, (280, 280, 520, 350)) > 20
                if phase_message_changed:
                    break
                if time.monotonic() >= deadline:
                    raise RuntimeError('ToTheFront Space did not visibly change the phase message')
                time.sleep(0.1)
            if rgb_pixels_in(after_phase, (130, 188, 73), (0, 0, 640, 480)) < 100000:
                raise RuntimeError('ToTheFront Space did not advance or redraw the phase')
            if args.probe_tothefront_move_diag:
                time.sleep(3)
                qmp_send_key('spc')
                until(b'TTF_MOVE_CAND:', timeout=25)
                candidate = until(b'\n', timeout=10).strip()
                match_candidate = re.fullmatch(r'(\d+),(\d+),(\d+),(\d+),(\d+),(\d+),(\d+)', candidate)
                if not match_candidate:
                    raise RuntimeError('ToTheFront produced no movable unit: '+candidate)
                unit, row, col, sx, sy, dx, dy = map(int, match_candidate.groups())
                print(f'ToTheFront candidate unit={unit} cell={row},{col} '
                      f'screen={sx},{sy}->{dx},{dy}', flush=True)
                move_graphical_pointer(sx, sy)
                time.sleep(.2)
                graphical_mouse_button('left', True)
                time.sleep(.2)
                move_graphical_pointer(dx, dy)
                time.sleep(.3)
                graphical_mouse_button('left', False)
                until(b'TTF_MOVE_RESULT:', timeout=30)
                result = until(b'\n', timeout=10).strip()
                match_result = re.fullmatch(r'(\d+),(\d+),(\d+),(\d+)', result)
                if not match_result:
                    raise RuntimeError('ToTheFront produced no movement result: '+result)
                old_r, old_c, new_r, new_c = map(int, match_result.groups())
                if (old_r, old_c) != (row, col) or (new_r, new_c) == (old_r, old_c):
                    raise RuntimeError(f'ToTheFront unit did not move: {result}')
                print(f'PASS ToTheFront moved unit {unit}: {result}', flush=True)
                if args.probe_tothefront_fire_diag:
                    # Complete both movement phases and test each side's
                    # direct-fire phase. The disposable fixture places an
                    # enemy in an empty adjacent cell and reports positions.
                    for _ in range(2):
                        time.sleep(3)
                        qmp_send_key('spc')
                    for expected_player in range(2):
                        until(b'TTF_FIRE_CAND:', timeout=30)
                        fire_candidate = until(b'\n', timeout=10).strip()
                        fire_match = re.fullmatch(
                            r'(\d+),(\d+),(\d+),(\d+),(\d+),(\d+),(\d+)',
                            fire_candidate)
                        if not fire_match:
                            raise RuntimeError('ToTheFront has no direct-fire fixture: '+fire_candidate)
                        player, attacker, target, sx, sy, dx, dy = map(int, fire_match.groups())
                        if player != expected_player:
                            raise RuntimeError(f'Unexpected direct-fire player {player}')
                        time.sleep(3)
                        move_graphical_pointer(sx, sy)
                        graphical_mouse_button('left', True)
                        time.sleep(.3)
                        move_graphical_pointer(dx, dy)
                        time.sleep(.3)
                        graphical_mouse_button('left', False)
                        until(b'TTF_FIRE_RESULT:', timeout=45)
                        fire_result = until(b'\n', timeout=10).strip()
                        result_match = re.fullmatch(r'(\d+),(\d+),(-?\d+),(-?\d+)', fire_result)
                        if not result_match:
                            raise RuntimeError('ToTheFront fire result malformed: '+fire_result)
                        got_player, fired, vis0, vis1 = map(int, result_match.groups())
                        if got_player != player or fired != 1:
                            raise RuntimeError(f'ToTheFront direct fire failed: player={player}, '
                                               f'fired={fired}, visibility={vis0},{vis1}')
                        print(f'PASS ToTheFront direct fire player {player}, '
                              f'attacker {attacker}, target {target}', flush=True)
                        if expected_player == 0:
                            time.sleep(3)
                            qmp_send_key('spc')
            qmp_send_key('esc')
            run_graphical_terminal_command(
                'tothefront-exit-smoke', '40+2;', 'ans=0x2A=42', timeout=20)
            command('zstatus', 'failed=0')
            print('PASS ToTheFront setup, map, phase input, Escape and terminal recovery',
                  flush=True)
            raise SystemExit(0)
        if args.probe_span_strut:
            focus_graphical_terminal()
            run_graphical_terminal_command('span-strut-ready', '40+2;', 'ans=0x2A=42')
            span_frame = None
            if not args.probe_strut_spring:
                span_workers_before = command(
                    'zstatus', 'keyboard_focus=Terminal', timeout=10)
                span_worker_ids_before = re.findall(
                    r'guest_task\[(\d+)\]: name=(?:Song|Animate) parent=Terminal',
                    span_workers_before)
                type_graphical_prompt_line(
                    'span-launch', 'ExeFile2("/Apps/Span/Run.ZC");')
                qmp_send_key('ret')
                require_graphical_text('span-help', 'Build a bridge to hold-up', timeout=15)
                # Dismiss the popup by clicking OK. A Return key-up can remain in
                # the app queue and satisfy Span's subsequent Shift+Escape
                # key-up wait before the exit path is actually under observation.
                move_graphical_pointer(120, 172)
                graphical_mouse_button('left', True)
                time.sleep(0.1)
                graphical_mouse_button('left', False)
                time.sleep(0.5)
                # App message loops can own terminal focus directly; do not assume
                # that the shared Server task remains the keyboard focus target.
                command('zstatus', 'keyboard_focus=', timeout=10)
                span_frame = graphical_screen('span-initial-frame')
                if not re.search(r'nonblack_pixels=(\d+) of 480000',
                                 command('zstatus', 'nonblack_pixels=')):
                    raise RuntimeError('Span did not report framebuffer output')
                if args.probe_span_save:
                    move_graphical_pointer(700, 500)
                    time.sleep(.3)
                    empty_bridge = graphical_screen('span-save-before-edit')
                    qmp_send_key('m')
                    move_graphical_pointer(400, 450)
                    time.sleep(.2)
                    graphical_mouse_button('left', True)
                    time.sleep(.15)
                    graphical_mouse_button('left', False)
                    move_graphical_pointer(700, 500)
                    time.sleep(.5)
                    edited_bridge = graphical_screen('span-save-edited')
                    bounds = (380, 430, 420, 470)
                    edit_diff = rgb_diff_count(empty_bridge, edited_bridge, bounds)
                    if edit_diff < 10:
                        raise RuntimeError(f'Span mass placement did not visibly change bridge: {edit_diff}')
                    qmp_send_keys(['ctrl', 'a'])
                    require_graphical_text('span-save-form', 'FileName:', timeout=20)
                    qmp_send_key('esc')
                    time.sleep(1)
                    saved = command('zc Print("%s%s=%d\\n","SPAN","_FILE",'
                                    'FileFind("/Home/Span/Game.DATA"));', 'SPAN_FILE=')
                    if 'SPAN_FILE=1' not in saved:
                        raise RuntimeError('Span save did not create /Home/Span/Game.DATA:\n'+saved)
                    print('PASS Span edited bridge saved to writable disk', flush=True)
                    qmp_send_keys(['ctrl', 'n'])
                    time.sleep(.5)
                    reset_bridge = graphical_screen('span-save-reset')
                    if rgb_diff_count(edited_bridge, reset_bridge, bounds) < 10:
                        raise RuntimeError('Span New did not remove the test mass')
                    qmp_send_keys(['ctrl', 'o'])
                    chooser = require_graphical_text('span-open-dialog', 'Game.DATA', timeout=30,
                                                    foreground_threshold=80000)
                    for row_index, line in enumerate(chooser[3].splitlines()):
                        if 'Game.DATA' in line:
                            move_graphical_pointer(line.index('Game.DATA') * 8 + 12, row_index * 8 + 5)
                            break
                    time.sleep(.3)
                    graphical_mouse_button('left', True)
                    time.sleep(.15)
                    graphical_mouse_button('left', False)
                    qmp_send_key('esc')
                    move_graphical_pointer(700, 500)
                    deadline = time.monotonic() + 20
                    while True:
                        time.sleep(.4)
                        reopened = graphical_screen('span-save-reopened')
                        if (rgb_diff_count(edited_bridge, reopened, bounds) < 10 and
                                rgb_diff_count(reset_bridge, reopened, bounds) >= 10):
                            break
                        if time.monotonic() >= deadline:
                            raise RuntimeError('Span did not restore the saved test mass')
                    print('PASS Span chooser reopened the saved edited bridge', flush=True)
                # Send a complete chord after dismissing help by mouse so there is
                # no unrelated Return key-up queued for Span's exit wait.
                qmp_send_keys(['shift', 'esc'])
                deadline = time.monotonic() + 10
                span_exit_status = ''
                while time.monotonic() < deadline:
                    span_exit_status = command(
                        'zstatus', 'keyboard_focus=', timeout=10)
                    if re.search(r'keyboard_focus=Terminal(?:\s|$)', span_exit_status):
                        break
                    time.sleep(0.2)
                if not re.search(r'keyboard_focus=Terminal(?:\s|$)', span_exit_status):
                    raise RuntimeError(
                        'Span did not return focus to terminal after Shift+Escape:\n' +
                        span_exit_status)
                span_worker_ids_after = re.findall(
                    r'guest_task\[(\d+)\]: name=(?:Song|Animate) parent=Terminal',
                    span_exit_status)
                if span_worker_ids_after != span_worker_ids_before:
                    raise RuntimeError(
                        'Span exit did not restore the original Song/Animate tasks: '
                        f'before={span_worker_ids_before}, after={span_worker_ids_after}\n' +
                        span_exit_status)
                focus_graphical_terminal()
                run_graphical_terminal_command('span-exit-smoke', '40+2;', 'ans=0x2A=42', timeout=20)
                print('PASS Span bridge entry, instructions, graphical frame and Shift+Escape recovery',
                      flush=True)

                if args.probe_span_cold:
                    command('zvol', 'flush=yes')
                    command('zstatus', 'failed=0')
