        if args.probe_3d_apps:
            command('zload /Tests/ProgramCatalog.ZC',
                    'zc: loaded /Tests/ProgramCatalog.ZC')
            mesh_output = command(
                'zc Print("3d_mesh_fixture_compile=%d\\n",'
                'StockCatalogCompile("/Tests/Sprite3DMesh.ZC"));',
                '3d_mesh_fixture_compile=', timeout=45)
            mesh_compiled = '3d_mesh_fixture_compile=1' in mesh_output
            print(('COMPILES ' if mesh_compiled else 'BLOCKED ')+
                  '/Tests/Sprite3DMesh.ZC', flush=True)
            if mesh_compiled:
                command('zload /Tests/Sprite3DMesh.ZC',
                        'zc: loaded /Tests/Sprite3DMesh.ZC')
                command('zcall Sprite3DMeshChecks',
                        'zc => 0x000000000000002a')
            interpolation_output = command(
                'zc Print("3d_interpolation_fixture_compile=%d\\n",'
                'StockCatalogCompile("/Tests/Sprite3DInterpolation.ZC"));',
                '3d_interpolation_fixture_compile=', timeout=45)
            interpolation_compiled = '3d_interpolation_fixture_compile=1' in interpolation_output
            print(('COMPILES ' if interpolation_compiled else 'BLOCKED ')+
                  '/Tests/Sprite3DInterpolation.ZC', flush=True)
            if interpolation_compiled:
                command('zload /Tests/Sprite3DInterpolation.ZC',
                        'zc: loaded /Tests/Sprite3DInterpolation.ZC')
                command('zcall Sprite3DInterpolationChecks',
                        'zc => 0x000000000000002a')
            app_probes = (
                ('/Apps/GrModels/Run.ZC', '/Apps/GrModels/Run.ZC'),
                ('/Apps/KeepAway/Run.ZC', '/Tests/KeepAwayCompile.ZC'),
                ('/Apps/Titanium/Run.ZC', '/Tests/TitaniumCompile.ZC'),
            )
            app_results = []
            for path, compile_path in app_probes:
                output = command('zc Print("3d_catalog=%d\\n",'
                                 f'StockCatalogCompile("{compile_path}"));',
                                 '3d_catalog=', timeout=45)
                compiled = '3d_catalog=1' in output
                app_results.append({'path': path, 'compiled': compiled,
                                    'compile_path': compile_path,
                                    'output': output})
                print(('COMPILES ' if compiled else 'BLOCKED ')+path,
                      flush=True)
            service_output = command(
                'zc Print("3d_services_compile=%d\\n",'
                'StockCatalogCompile("/Tests/Sprite3DServices.ZC"));',
                '3d_services_compile=', timeout=45)
            services_compiled = '3d_services_compile=1' in service_output
            print(('COMPILES ' if services_compiled else 'BLOCKED ')+
                  '/Tests/Sprite3DServices.ZC', flush=True)
            service_runtime_output = ''
            service_runtime_passed = False
            if services_compiled:
                command('zload /Tests/Sprite3DServices.ZC',
                        'zc: loaded /Tests/Sprite3DServices.ZC')
                service_runtime_output = command(
                    'zcall Sprite3DServiceChecks',
                    'zc =>')
                service_runtime_passed = (
                    'zc => 0x000000000000002a' in service_runtime_output)
            height_output = command(
                'zc Print("3d_height_fixture_compile=%d\\n",'
                'StockCatalogCompile("/Tests/FormatHeight.ZC"));',
                '3d_height_fixture_compile=')
            if '3d_height_fixture_compile=1' not in height_output:
                raise RuntimeError('3D app formatter fixture did not compile:\n'+
                                   height_output)
            command('zload /Tests/FormatHeight.ZC',
                    'zc: loaded /Tests/FormatHeight.ZC')
            command('zcall FormatHeightChecks',
                    'zc => 0x000000000000002a')
            report = {
                'commit': json.loads((ROOT/'upstream/pinned/UPSTREAM.json').read_text())['commit'],
                'mode': 'isolated CCF_JUST_LOAD compile plus runtime service fixture',
                'applications': app_results,
                'mesh_fixture_compiled': mesh_compiled,
                'mesh_fixture_output': mesh_output,
                'interpolation_fixture_compiled': interpolation_compiled,
                'interpolation_fixture_output': interpolation_output,
                'service_fixture_compiled': services_compiled,
                'service_output': service_output,
                'service_runtime_output': service_runtime_output,
                'service_runtime_passed': service_runtime_passed,
            }
            (ROOT/'build/3d-apps-compile.json').write_text(
                json.dumps(report, indent=2)+'\n')
            if (not mesh_compiled or not interpolation_compiled or
                    not services_compiled or not service_runtime_passed or
                    not all(item['compiled'] for item in app_results)):
                print('BLOCKED 3D service/app gate: sprite compile or runtime checks failed',
                      flush=True)
                raise SystemExit(2)
            command('zstatus', 'failed=0')
            focus_graphical_terminal()
            if args.probe_titanium_only:
                type_graphical_prompt_line('titanium-press-a-key', 'PressAKey;')
                qmp_send_key('ret')
                require_graphical_text('titanium-press-a-key-prompt',
                                       'PRESS A KEY', timeout=10)
                qmp_send_key('a')
                run_graphical_terminal_command(
                    'titanium-press-a-key-smoke', '40+2;', 'ans=0x2A=42',
                    timeout=20)
                type_graphical_prompt_line(
                    '3d-titanium-launch', 'BootstrapGuiTerminalTitaniumRun();')
                qmp_send_key('ret')
                require_graphical_text('3d-titanium-help',
                                       'Sweep side-to-side while shooting',
                                       timeout=15)
                before_input = command('zstatus', 'keyboard_focus=')
                print('TITANIUM WAIT STATUS BEFORE KEY\n'+before_input, flush=True)
                qmp_send_key('a')
                try:
                    require_graphical_text_absent('3d-titanium-after-key',
                                                  'PRESS A KEY', timeout=5)
                except RuntimeError as ui_error:
                    try:
                        after_input = command('zstatus', 'keyboard_focus=', timeout=5)
                    except RuntimeError as status_error:
                        after_input = str(status_error)
                    screen = graphical_screen('3d-titanium-after-key-timeout')
                    raise RuntimeError(
                        f'{ui_error}\nTITANIUM STATUS AFTER KEY\n{after_input}\n'
                        f'POST-KEY FRAME TEXT\n{screen[3]}') from ui_error
                after_input = command('zstatus', 'keyboard_focus=', timeout=5)
                print('TITANIUM GAME STATUS AFTER KEY\n'+after_input, flush=True)
                if 'keyboard_focus=Titanium' not in after_input:
                    raise RuntimeError('Titanium did not retain keyboard focus after starting')
                frame_match = re.search(r'mesh_overlay: calls=(\d+)', after_input)
                if not frame_match or int(frame_match.group(1)) == 0:
                    raise RuntimeError('Titanium did not render a gameplay frame after starting')
                player_bounds = (0, 400, 800, 600)
                before_left = graphical_screen('3d-titanium-before-left')
                before_size, before_center = largest_color_component_center(
                    before_left, (5, 124, 126), player_bounds)
                if before_center is None:
                    raise RuntimeError('could not identify Titanium player sprite before movement')
                qmp_key_edges(['left'], True)
                time.sleep(1.0)
                left_held_status = command('zstatus', 'keyboard_focus=Titanium', timeout=5)
                print('TITANIUM LEFT-HELD STATUS\n'+left_held_status, flush=True)
                if 'keyboard_bitmap: left=1' not in left_held_status:
                    raise RuntimeError('held left arrow did not set kbd.down_bitmap')
                time.sleep(1.0)
                during_left = graphical_screen('3d-titanium-during-left')
                qmp_key_edges(['left'], False)
                time.sleep(0.2)
                after_size, after_center = largest_color_component_center(
                    during_left, (5, 124, 126), player_bounds)
                # Titanium's projected player is small at the initial camera
                # distance; even a two-second hold may shift its detected
                # sprite center by less than 30 pixels. The arrow bitmap is
                # checked above, so require directional displacement without
                # assuming a specific per-frame speed.
                if after_center is None or after_center[0] >= before_center[0] - 10:
                    raise RuntimeError('Titanium left arrow did not move the player: '
                        f'before={before_center}/{before_size}, '
                        f'after={after_center}/{after_size}')
                print('PASS Titanium left arrow moves player: '
                      f'{before_center} -> {after_center}', flush=True)
                qmp_key_edges(['right'], True)
                time.sleep(1.0)
                right_held_status = command('zstatus', 'keyboard_focus=Titanium', timeout=5)
                print('TITANIUM RIGHT-HELD STATUS\n'+right_held_status, flush=True)
                if not re.search(r'keyboard_bitmap:.*\bright=1\b', right_held_status):
                    raise RuntimeError('held right arrow did not set kbd.down_bitmap')
                time.sleep(1.0)
                during_right = graphical_screen('3d-titanium-during-right')
                qmp_key_edges(['right'], False)
                time.sleep(0.2)
                right_size, right_center = largest_color_component_center(
                    during_right, (5, 124, 126), player_bounds)
                if right_center is None or right_center[0] <= after_center[0] + 10:
                    raise RuntimeError('Titanium right arrow did not move the player: '
                        f'before={after_center}/{after_size}, '
                        f'after={right_center}/{right_size}')
                print('PASS Titanium right arrow moves player: '
                      f'{after_center} -> {right_center}', flush=True)
                frames_before_space = int(frame_match.group(1))
                qmp_key_edges(['spc'], True)
                time.sleep(0.3)
                qmp_key_edges(['spc'], False)
                time.sleep(0.5)
                after_space = command('zstatus', 'keyboard_focus=Titanium', timeout=5)
                frame_match = re.search(r'mesh_overlay: calls=(\d+)', after_space)
                if not frame_match or int(frame_match.group(1)) <= frames_before_space:
                    raise RuntimeError('Titanium gameplay frame did not advance after Space')
                qmp_send_key('esc')
                run_graphical_terminal_command(
                    '3d-titanium-exit-smoke', '40+2;', 'ans=0x2A=42', timeout=20)
                command('zstatus', 'failed=0')
                print('PASS Titanium press-a-key, game frame, input and Escape recovery',
                      flush=True)
                raise SystemExit(0)
            # A dedicated full-game run should isolate KeepAway instead of
            # first running the separate GrModels color-popup interaction.
            # That popup has its own live acceptance path and can fail before
            # the long-running game probe is reached.
            if not (args.probe_keepaway_audio or args.probe_keepaway_full_game):
                type_graphical_prompt_line(
                    '3d-grmodels-launch',
                    'ExeFile2("/Apps/GrModels/Run.ZC");')
                qmp_send_key('ret')
                time.sleep(1)
                grmodels = graphical_screen('3d-grmodels-entry')
                print('GRMODELS ENTRY SCREEN\n'+grmodels[3], flush=True)
                move_graphical_pointer(53, 52)
                graphical_mouse_button('left', True)
                time.sleep(0.2)
                graphical_mouse_button('left', False)
                time.sleep(1)
                man_form = graphical_screen('3d-grmodels-man-form')
                print('GRMODELS MAN FORM\n'+man_form[3], flush=True)
                qmp_send_key('esc')
                require_graphical_text(
                    '3d-grmodels-man-color-shirt', 'Single-Sided means', timeout=12)

                def click_3d_color(name, current_marker, next_marker):
                    # Select the red entry in the first (single-sided, full-range)
                    # column. In the 800x600 UI it is the fifth eight-pixel row
                    # below the section header.
                    deadline = time.monotonic() + 12
                    attempt = 0
                    while True:
                        screen = graphical_screen(name+'-before')
                        # The first framebuffer read after the color-popup
                        # closes can capture the prompt while its DolDoc text is
                        # still being repainted. Accept the stable prefix for
                        # this particular repeat prompt; the subsequent `n`
                        # input and terminal recovery remain the real checks.
                        next_visible = next_marker in screen[3]
                        if next_marker == 'Do another':
                            # Some guest font/framebuffer captures lose a few
                            # letters in this prompt even though the question
                            # suffix is rendered. Treat its answer choices as the
                            # stable marker; the caller also checks generated
                            # mesh diagnostics before accepting the app path.
                            next_visible |= ('Do anot' in screen[3] or
                                             'y or n)?' in screen[3])
                        if next_visible:
                            return screen
                        if current_marker not in screen[3]:
                            # The picker can disappear before the next
                            # document repaint. Do not click through that
                            # transient frame or mistake it for completion.
                            if time.monotonic() >= deadline:
                                raise RuntimeError(
                                    f'{name}: color picker changed without showing '
                                    f'{next_marker!r}:\n'+screen[3])
                            time.sleep(.2)
                            continue
                        if time.monotonic() >= deadline:
                            diagnostic = command('zstatus', 'failed=')
                            raise RuntimeError(
                                f'{name}: color choice did not advance from '
                                f'{current_marker!r} to {next_marker!r}:\n'+
                                screen[3]+'\n'+diagnostic)
                        attempt += 1
                        time.sleep(0.25)
                        if attempt == 1:
                            move_graphical_pointer(100, 124)
                            graphical_mouse_button('left', True)
                            time.sleep(0.15)
                            graphical_mouse_button('left', False)
                        elif attempt == 2:
                            # PopUpMenu also supports Return on the highlighted
                            # DolDoc link; use it once if the click only hovered.
                            qmp_send_key('ret')
                        else:
                            move_graphical_pointer(100, 124)
                            graphical_mouse_button('left', True)
                            time.sleep(0.15)
                            graphical_mouse_button('left', False)
                        print(f'3D color selection {name} attempt {attempt}', flush=True)
                        time.sleep(0.35)

                click_3d_color('3d-grmodels-man-pants', 'Shirt', 'Pants')
                click_3d_color('3d-grmodels-man-skin', 'Pants', 'Skin')
                click_3d_color('3d-grmodels-man-shoes', 'Skin', 'Shoes')
                click_3d_color('3d-grmodels-man-generated', 'Shoes', 'Do another')
                man_generated = require_graphical_text(
                    '3d-grmodels-man-generated', 'y or n)?', timeout=20)
                if 'y or n)?' not in man_generated[3]:
                    raise RuntimeError('GrModels Man did not finish mesh generation')
                print('PASS GrModels Man mesh generation reached its repeat prompt',
                      flush=True)
                qmp_send_key('n')
                time.sleep(0.5)
                graphical_screen('3d-grmodels-man-after-exit')
                run_graphical_terminal_command(
                    '3d-grmodels-man-exit-smoke', '40+2;', 'ans=0x2A=42', timeout=20)
                command('zstatus', 'failed=0')
                mesh_diag = ''.join(command(
                    line, 'zc: executed', timeout=20)
                    for line in (
                        'zc Print("3d_live_mesh=%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_last_vertices,'
                        'sprite_debug_mesh_last_triangles,'
                        'sprite_debug_mesh_last_result,'
                        'sprite_debug_mesh_last_work);',
                        'zc Print("3d_live_color_pixels=%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_last_color,'
                        'sprite_debug_mesh_last_lit_color,'
                        'sprite_debug_mesh_pixel_attempts,'
                        'sprite_debug_mesh_pixel_writes,'
                        'sprite_debug_mesh_pixel_min_x,'
                        'sprite_debug_mesh_pixel_min_y);',
                        'zc Print("3d_live_color_masks=%d,%d,%d\\n",'
                        'sprite_debug_mesh_raw_color_mask,'
                        'sprite_debug_mesh_lit_color_mask,'
                        'sprite_debug_mesh_pixel_color_mask);',
                        'zc Print("3d_live_bounds_masks=%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_pixel_max_x,'
                        'sprite_debug_mesh_pixel_max_y,'
                        'sprite_debug_type_mask_failures,'
                        'sprite_debug_type_mask_last_type,'
                        'sprite_debug_type_mask_last_size);',
                        'zc Print("3d_live_choices=%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_lighting_choice_count,'
                        'sprite_debug_lighting_choices[0],'
                        'sprite_debug_lighting_choices[1],'
                        'sprite_debug_lighting_choices[2],'
                        'sprite_debug_lighting_choices[3]);',
                        'zc Print("3d_live_target=%d,%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_target_dc_is_bootstrap,'
                        'sprite_debug_mesh_target_body_is_graphics,'
                        'sprite_debug_mesh_target_body_is_foreground,'
                        'sprite_debug_mesh_target_last_x,'
                        'sprite_debug_mesh_target_last_y,'
                        'sprite_debug_mesh_target_last_pixel,'
                        'sprite_debug_mesh_target_last_index);',
                        'zc Print("3d_live_target_window=%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_target_left,'
                        'sprite_debug_mesh_target_right,'
                        'sprite_debug_mesh_target_top,'
                        'sprite_debug_mesh_target_bottom,'
                        'sprite_debug_mesh_target_scroll_x,'
                        'sprite_debug_mesh_target_scroll_y);'))
                print('GRMODELS MAN RASTER DIAGNOSTIC\n'+mesh_diag, flush=True)

                type_graphical_prompt_line(
                    '3d-grmodels-ball-launch',
                    'ExeFile2("/Apps/GrModels/Run.ZC");')
                qmp_send_key('ret')
                # The previous Man run leaves its menu and repeat prompt in
                # the document until the new run executes DocClear. Do not
                # click the stale Ball button before that clear completes.
                require_graphical_text_absent('3d-grmodels-ball-clear',
                                              'Do another', timeout=20)
                require_graphical_text('3d-grmodels-ball-entry', 'Make a CSprite model',
                                       timeout=12)
                ball_form = None
                # The GrModels chooser is a DolDoc menu in the left terminal;
                # keyboard arrows go to the command prompt, so select the Ball
                # link with the pointer and verify the form before continuing.
                for y in (84, 88, 80, 92):
                    move_graphical_pointer(54, y)
                    graphical_mouse_button('left', True)
                    time.sleep(0.15)
                    graphical_mouse_button('left', False)
                    try:
                        ball_form = require_graphical_text(
                            '3d-grmodels-ball-form', 'Longitude Faces', timeout=2)
                        break
                    except RuntimeError:
                        screen = graphical_screen('3d-grmodels-ball-entry-retry')
                        if 'Make a CSprite model' not in screen[3]:
                            raise RuntimeError('GrModels chooser left its entry screen '
                                               'without opening the Ball form:\n'+screen[3])
                if ball_form is None:
                    raise RuntimeError('GrModels Ball form did not open after clicking '
                                       'the Ball link')
                if 'Radius' not in ball_form[3] or 'Lattitude Rings' not in ball_form[3]:
                    raise RuntimeError('GrModels Ball form is missing expected fields:\n'+
                                       ball_form[3])
                qmp_send_key('esc')
                require_graphical_text('3d-grmodels-ball-color', 'Single-Sided means',
                                       timeout=12)
                click_3d_color('3d-grmodels-ball-generated',
                               'Single-Sided means', 'Vertices:')
                ball_generated = require_graphical_text(
                    '3d-grmodels-ball-generated', 'Vertices:', timeout=25)
                require_graphical_text('3d-grmodels-ball-repeat', 'Do another', timeout=10)
                ball_sprite_pixels = rgb_pixels_in(
                    ball_generated, (170, 0, 170), (8, 16, 400, 591))
                if ball_sprite_pixels < 100:
                    raise RuntimeError('GrModels Ball generated a sprite entry but its '
                                       'purple mesh was not visible in the document: '
                                       f'{ball_sprite_pixels} matching pixels')
                print('PASS GrModels Ball sprite visible inline: '
                      f'{ball_sprite_pixels} purple pixels', flush=True)
                print('PASS GrModels Ball mesh generation; '+
                      next((line.strip() for line in ball_generated[3].splitlines()
                            if 'Vertices:' in line), 'Vertices reported'), flush=True)
                ball_render_diag = command(
                    'zc Print("3d_ball_doc_sprite=%d,%d,%d,%d,%d,%d,%d\\n",'
                    'sprite_debug_doc_sprite_calls,sprite_debug_doc_sprite_doc_is_put,'
                    'sprite_debug_doc_sprite_doc_is_display,'
                    'sprite_debug_doc_sprite_doc_window_is_current,'
                    'sprite_debug_doc_sprite_entry_type,sprite_debug_doc_sprite_has_bin,'
                    'sprite_debug_mesh_calls);', 'zc: executed', timeout=20)
                print('GRMODELS BALL DOCUMENT/RENDER DIAGNOSTIC\\n'+ball_render_diag,
                      flush=True)
                command(
                    'zc I64 GrModelsBallSpriteEntryCheck(){'
                    'if (sprite_debug_doc_sprite_calls>0 && '
                    '(sprite_debug_doc_sprite_entry_type&0xFF)==DOCT_SPRITE && '
                    'sprite_debug_doc_sprite_has_bin) return 42; return 0;};',
                    'zc: executed')
                command('zcall GrModelsBallSpriteEntryCheck',
                        'zc => 0x000000000000002a')
                qmp_send_key('n')
                time.sleep(0.5)
                graphical_screen('3d-grmodels-ball-after-exit')
                run_graphical_terminal_command(
                    '3d-grmodels-ball-exit-smoke', '40+2;', 'ans=0x2A=42', timeout=20)
                command('zstatus', 'failed=0')
                mesh_diag = ''.join(command(
                    line, 'zc: executed', timeout=20)
                    for line in (
                        'zc Print("3d_live_mesh=%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_last_vertices,'
                        'sprite_debug_mesh_last_triangles,'
                        'sprite_debug_mesh_last_result,'
                        'sprite_debug_mesh_last_work);',
                        'zc Print("3d_live_color_pixels=%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_last_color,'
                        'sprite_debug_mesh_last_lit_color,'
                        'sprite_debug_mesh_pixel_attempts,'
                        'sprite_debug_mesh_pixel_writes,'
                        'sprite_debug_mesh_pixel_min_x,'
                        'sprite_debug_mesh_pixel_min_y);',
                        'zc Print("3d_live_color_masks=%d,%d,%d\\n",'
                        'sprite_debug_mesh_raw_color_mask,'
                        'sprite_debug_mesh_lit_color_mask,'
                        'sprite_debug_mesh_pixel_color_mask);',
                        'zc Print("3d_live_bounds_masks=%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_pixel_max_x,'
                        'sprite_debug_mesh_pixel_max_y,'
                        'sprite_debug_type_mask_failures,'
                        'sprite_debug_type_mask_last_type,'
                        'sprite_debug_type_mask_last_size);',
                        'zc Print("3d_live_choices=%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_lighting_choice_count,'
                        'sprite_debug_lighting_choices[0],'
                        'sprite_debug_lighting_choices[1],'
                        'sprite_debug_lighting_choices[2],'
                        'sprite_debug_lighting_choices[3]);',
                        'zc Print("3d_live_target=%d,%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_target_dc_is_bootstrap,'
                        'sprite_debug_mesh_target_body_is_graphics,'
                        'sprite_debug_mesh_target_body_is_foreground,'
                        'sprite_debug_mesh_target_last_x,'
                        'sprite_debug_mesh_target_last_y,'
                        'sprite_debug_mesh_target_last_pixel,'
                        'sprite_debug_mesh_target_last_index);',
                        'zc Print("3d_live_target_window=%d,%d,%d,%d,%d,%d\\n",'
                        'sprite_debug_mesh_target_left,'
                        'sprite_debug_mesh_target_right,'
                        'sprite_debug_mesh_target_top,'
                        'sprite_debug_mesh_target_bottom,'
                        'sprite_debug_mesh_target_scroll_x,'
                        'sprite_debug_mesh_target_scroll_y);'))
                print('GRMODELS BALL RASTER DIAGNOSTIC\n'+mesh_diag, flush=True)

            if args.probe_keepaway_audio:
                if args.probe_keepaway_audio_timer:
                    command('zc extern I64 ZcSoundTimerEnable(); '
                            'extern I64 ZcSoundTimerTotalIrqs(); '
                            'extern I64 ZcSoundCurrentHz();', 'zc: executed')
                    command('zc Print("keepaway_timer=%d\\n",ZcSoundTimerEnable);',
                            'keepaway_timer=1')
                keepaway_audio_path = pathlib.Path(os.environ['ZEAL_AUDIO_CAPTURE_PATH'])
                print('KEEP_AWAY_AUDIO_START=' + str(
                    keepaway_audio_path.stat().st_size if keepaway_audio_path.exists() else 44),
                      flush=True)
            type_graphical_prompt_line(
                '3d-keepaway-launch',
                'ExeFile2("/Apps/KeepAway/Run.ZC");')
            qmp_send_key('ret')
            require_graphical_text('3d-keepaway-help', 'Pass or hand-off',
                                   timeout=15)
            # This one-button PopUpOk is positioned at the top-left of the
            # primary graphical terminal; click the center of its OKAY link.
            move_graphical_pointer(192, 116)
            graphical_mouse_button('left', True)
            time.sleep(0.2)
            graphical_mouse_button('left', False)
            time.sleep(0.4)
